# -*- coding: utf-8 -*-
from html import escape as e

def copy(s, kicker):
 return f'''<div class="im-copy"><span class="eyebrow">{kicker}</span><h1>{s['title']}</h1><p>{e(s['desc'])}</p><div class="actions"><a class="btn" href="#contact">{e(s['cta'])}</a><a class="btn outline" href="#experience">경험 살펴보기</a></div></div>'''

def image(name,alt,cls=''):
 return f'<img class="{cls}" src="../assets/{name}.webp" alt="{e(alt)}" width="1600" height="1000" decoding="async">'

def render_interaction_hero(s):
 kind=s['interaction'];c=copy(s,s['en'])
 toggle='<div class="im-controls wrap"><span>INTERACTIVE EDITION</span><button class="im-motion-toggle" type="button" aria-pressed="true" hidden>모션 줄이기</button></div>'
 if kind=='kinetic':
  visual=f'''<div class="im-playground im-tilt" data-tilt><div class="im-orbit-ring" aria-hidden="true"></div><div class="im-type-card" aria-hidden="true"><span>IDEAS IN MOTION</span><strong>MAKE<br>IT MOVE.</strong><i>BRAND / DIGITAL / EXPERIENCE</i></div><div class="im-photo-card">{image('office','크리에이티브 업무 공간 참고 사진')}<span>생각이 경험으로 바뀌는 곳.</span></div><span class="im-sticker" aria-hidden="true">LET’S<br>PLAY</span></div>'''
  body=f'<div class="wrap im-hero im-hero--kinetic">{c}{visual}</div><div class="im-marquee" aria-hidden="true"><div>MAKE IT MOVE. &nbsp; BRAND IN PLAY. &nbsp; MAKE IT MOVE. &nbsp; BRAND IN PLAY. &nbsp;</div></div>'
 elif kind=='chapters':
  visual='''<div class="im-product im-tilt" data-tilt><div class="im-product-orbit" aria-hidden="true"></div><div class="im-product-window"><div class="im-window-top"><span>ORBIT / EXPERIENCE</span><i aria-hidden="true"></i></div><div class="im-product-tabs" role="group" aria-label="제품 설계 단계"><button type="button" data-product-step="0" aria-pressed="true">기획</button><button type="button" data-product-step="1" aria-pressed="false">구조</button><button type="button" data-product-step="2" aria-pressed="false">경험</button></div><div class="im-product-screen" data-product-scene="0"><div class="im-product-grid" aria-hidden="true"><i></i><i></i><i></i><i></i></div><span>아이디어를 명료하게.</span><strong id="im-product-title" aria-live="polite">문제의 중심을 찾습니다.</strong><p id="im-product-description">제품이 필요한 상황과 사용자의 목적을 먼저 정리합니다.</p><span class="im-product-label">서비스 화면 구성 예시</span></div></div></div>'''
  body=f'<div class="wrap im-hero im-hero--product">{c}{visual}</div>'
 elif kind=='scrubber':
  visual=f'''<div class="im-machine-visual im-spotlight" data-spotlight>{image('machinery','기계 설비의 구조를 보여주는 참고 사진')}<div class="im-blueprint-grid" aria-hidden="true"></div><div class="im-machine-cross" aria-hidden="true"></div><span class="im-machine-tag">MATERIAL / FORM / PROCESS</span><span class="im-machine-caption">형태 너머의 조건을 읽습니다.</span></div>'''
  body=f'<div class="wrap im-hero im-hero--machine">{c}{visual}</div>'
 elif kind=='gallery':
  body=f'''<div class="wrap im-hero im-hero--living">{c}<div class="im-room-visual" data-parallax>{image('interior','햇빛이 드는 주거 공간 참고 사진')}<span class="im-room-label">A PLACE<br>TO BE.</span></div><p class="im-room-caption">질감과 빛, 그리고 생활의 리듬.</p></div>'''
 elif kind=='flavor':
  body=f'''<div class="wrap im-hero im-hero--coffee">{c}<div class="im-coffee-world" data-flavor-scene="balanced"><div class="im-coffee-ring" aria-hidden="true"></div><div class="im-coffee-photo" data-tilt>{image('coffee','커피를 내리는 과정 참고 사진')}</div><span class="im-coffee-type" aria-hidden="true">slow<br>notes.</span><span class="im-coffee-bean im-coffee-bean--one" aria-hidden="true"></span><span class="im-coffee-bean im-coffee-bean--two" aria-hidden="true"></span><div class="im-taste-card"><span>YOUR COFFEE MOOD</span><strong id="im-flavor-title" aria-live="polite">편안한 균형</strong><p id="im-flavor-description">고소함과 은은한 단맛이 떠오르는 한 잔.</p></div></div><div class="im-flavor-picker"><span>어떤 인상을 좋아하세요?</span><div role="group" aria-label="커피 취향 선택"><button type="button" data-flavor="bright" aria-pressed="false">산뜻한</button><button type="button" data-flavor="balanced" aria-pressed="true">균형 있는</button><button type="button" data-flavor="deep" aria-pressed="false">묵직한</button></div></div></div>'''
 else:
  posters=''.join(f'<div class="im-fan-card im-fan-card--{i}"><span>{word}</span>{image(pic,"문화 공간 분위기 참고 사진")}<strong>{label}</strong></div>' for i,word,pic,label in [(1,'EXPLORE','studio','보다.'),(2,'MAKE','craft','만들다.'),(3,'SHARE','office','나누다.')])
  body=f'<div class="wrap im-hero im-hero--culture">{c}<div class="im-poster-fan im-tilt" data-tilt aria-hidden="true">{posters}</div></div>'
 return toggle+body

def render_interaction_experience(s):
 kind=s['interaction']
 if kind=='kinetic':
  return '''<section class="im-experience im-play-section" id="experience"><div class="wrap"><div class="im-section-head im-reveal"><div><span class="eyebrow">ONE BRAND, MANY EXPRESSIONS</span><h2>어떤 모습으로<br>기억되고 싶나요?</h2></div><p>키워드를 골라 브랜드의 다른 표정을 살펴보세요.</p></div><div class="im-brand-switch" data-brand-scene="brand"><div class="im-brand-choices" role="group" aria-label="브랜드 표현 방식"><button type="button" data-brand="brand" aria-pressed="true">브랜드</button><button type="button" data-brand="digital" aria-pressed="false">디지털</button><button type="button" data-brand="content" aria-pressed="false">콘텐츠</button></div><div class="im-brand-art" aria-hidden="true"><span class="im-brand-word">FORM.</span><span class="im-brand-shape"></span></div><div class="im-brand-copy" aria-live="polite"><h3 id="im-brand-title">성격이 보이는 첫인상.</h3><p id="im-brand-description">색과 형태, 언어의 방향을 하나의 인상으로 엮습니다.</p></div></div></div></section>'''
 if kind=='chapters':
  chapters=[('문제를 발견하다.','불편한 순간과 필요한 결과를 구체적으로 살펴봅니다.'),('흐름을 연결하다.','정보를 정리하고, 다음 행동이 자연스럽게 이어지도록 구성합니다.'),('경험을 다듬다.','누르고 이동하는 과정을 확인하며 반응의 리듬을 조율합니다.')]
  rows=''.join(f'<article class="im-chapter im-reveal" data-chapter="{i}"><span>{label}</span><h3>{title}</h3><p>{text}</p></article>' for i,(label,(title,text)) in enumerate(zip(['DISCOVER','CONNECT','REFINE'],chapters)))
  return f'''<section class="im-experience im-chapter-section" id="experience"><div class="wrap im-chapter-grid"><div class="im-chapter-stage"><span class="eyebrow">FROM IDEA TO EXPERIENCE</span><h2>생각이 흐르고,<br>경험이 됩니다.</h2><div class="im-scroll-object" aria-hidden="true"><span></span><i></i><b></b></div><div class="im-chapter-meter" aria-hidden="true"><span></span></div><p id="im-chapter-current">문제를 발견하다.</p></div><div class="im-chapters">{rows}</div></div></section>'''
 if kind=='scrubber':
  return '''<section class="im-experience im-process-section" id="experience"><div class="wrap"><div class="im-section-head im-reveal"><div><span class="eyebrow">A CLOSER LOOK AT THE PROCESS</span><h2>과정을 움직여,<br>제작의 흐름을 보다.</h2></div><p>슬라이더나 단계 버튼으로 검토 순서를 살펴보세요.</p></div><div class="im-process" data-process="0"><div class="im-part-stage" aria-hidden="true"><div class="im-part-grid"></div><div class="im-part im-part--back"></div><div class="im-part im-part--middle"></div><div class="im-part im-part--front"></div><span>FORM STUDY / 구성 예시</span></div><div class="im-process-copy"><span class="eyebrow">PROCESS REVIEW</span><h3 id="im-process-title" aria-live="polite">도면의 조건을 확인합니다.</h3><p id="im-process-description">형상과 치수, 필요한 소재와 사용 환경을 함께 정리합니다.</p><label class="im-range-label" for="im-process-range">제작 검토 단계</label><input id="im-process-range" type="range" min="0" max="2" step="1" value="0" aria-valuetext="도면 검토"><div class="im-process-steps" role="group" aria-label="제작 검토 단계 선택"><button type="button" data-process-step="0" aria-pressed="true">도면 검토</button><button type="button" data-process-step="1" aria-pressed="false">공정 검토</button><button type="button" data-process-step="2" aria-pressed="false">제작 협의</button></div></div></div></div></section>'''
 if kind=='gallery':
  cards=''.join(f'<article class="im-room-card" role="group" aria-label="{i+1} / 3">{image(pic,alt)}<div><span>{kicker}</span><h3>{title}</h3><p>{text}</p></div></article>' for i,(pic,alt,kicker,title,text) in enumerate([('interior','거실의 가구 배치 참고 사진','LIVING','낮의 빛을 담은 거실.','부드러운 질감과 편안한 동선을 살펴봅니다.'),('stay','휴식을 위한 공간 참고 사진','REST','느리게 쉬어가는 방.','머무는 시간을 위한 소재와 분위기를 이야기합니다.'),('cafe','작은 상업 공간 참고 사진','GATHER','함께하는 작은 공간.','사람이 모이는 공간의 쓰임을 생각합니다.')]))
  return f'''<section class="im-experience im-gallery-section" id="experience"><div class="wrap"><div class="im-section-head im-reveal"><div><span class="eyebrow">ROOMS TO EXPLORE</span><h2>다른 장면으로<br>시선을 옮겨보세요.</h2></div><div class="im-gallery-controls"><button type="button" data-gallery-prev aria-label="이전 공간 보기">이전</button><button type="button" data-gallery-next aria-label="다음 공간 보기">다음</button></div></div><div class="im-room-track" tabindex="0" aria-label="공간 분위기 갤러리. 좌우로 스크롤하거나 이전·다음 버튼으로 이동하세요.">{cards}</div><div class="im-gallery-bottom"><p>공간 분위기 참고 이미지</p><span id="im-gallery-position" aria-live="polite">1 / 3</span></div></div></section>'''
 if kind=='flavor':
  items=[('향으로 고르기','먼저 떠오르는 인상부터.','과일처럼 산뜻한 향인지, 견과류처럼 편안한 향인지 이야기해 보세요. 정답보다 자신의 기억이 중요합니다.'),('도구와 함께 생각하기','같은 원두에도 다른 표정.','드립 도구와 물의 온도, 분쇄 정도에 따라 커피의 인상이 달라집니다. 사용 환경을 함께 알려주세요.'),('일상으로 가져가기','좋아하는 시간을 오래.','마시는 빈도와 보관 환경을 살펴 필요한 양과 관리 방법을 정리합니다.')]
  rows=''.join(f'<details class="im-coffee-detail" {"open" if i==0 else ""}><summary><span>{label}</span><i aria-hidden="true"></i></summary><div><h3>{title}</h3><p>{text}</p></div></details>' for i,(label,title,text) in enumerate(items))
  return f'''<section class="im-experience im-coffee-section" id="experience"><div class="wrap im-coffee-guide"><div class="im-reveal"><span class="eyebrow">FIND YOUR EVERYDAY CUP</span><h2>커피를 고르는<br>작은 기준들.</h2><p>궁금한 이야기를 열어보세요.</p></div><div>{rows}</div></div></section>'''
  
 items=[('space','SPACE','공간을 보다.','studio','전시와 휴식이 만나는 공간의 구성을 살펴보세요.'),('class','CLASS','손으로 만들다.','craft','취향과 호기심에서 출발하는 클래스 이야기를 나눠보세요.'),('together','TOGETHER','생각을 나누다.','office','함께하는 사람과 목적에 어울리는 시간을 이야기해요.')]
 cards=''.join(f'<button class="im-poster-choice" type="button" data-poster="{key}" aria-pressed="{str(i==0).lower()}" aria-controls="im-poster-description">{image(pic,"문화 공간 참고 사진")}<span>{kicker}</span><strong>{title}</strong><i aria-hidden="true">+</i></button>' for i,(key,kicker,title,pic,text) in enumerate(items))
 return f'''<section class="im-experience im-poster-section" id="experience"><div class="wrap"><div class="im-section-head im-reveal"><div><span class="eyebrow">PICK YOUR SCENE</span><h2>오늘, 어떤 경험을<br>겹쳐볼까요?</h2></div><p>마음이 가는 장면을 골라보세요.</p></div><div class="im-poster-choices" role="group" aria-label="문화 공간 경험 선택">{cards}</div><p id="im-poster-description" aria-live="polite">전시와 휴식이 만나는 공간의 구성을 살펴보세요.</p></div></section>'''
